import { test, expect } from '@playwright/test';
import { ensureCapboSession, fillAngularField } from './helpers/capbo-ui';

test.describe("Currencies business-rule validations", () => {
  test.setTimeout(30_000);

  // AC: currency.currencyCode only accepts exactly 3 uppercase letters
  test("code rejects lowercase (pattern [A-Z]{3})", async ({ page }) => {
    await ensureCapboSession(page, "/currency");
    await page.getByTestId("currency-create").click({ timeout: 15000 });
    const input = page.getByTestId("currency-code");
    await fillAngularField(page, input, "abc");
    await page.keyboard.press('Tab');
    await expect(input.locator('xpath=ancestor::mat-form-field[1]').locator('mat-error').first().or(page.locator('mat-error').first())).toBeVisible({ timeout: 5000 });
    await expect(page.getByTestId("currency-save")).toBeDisabled();
    await page.getByTestId("currency-cancel").click({ timeout: 8000 }).catch(() => {});
  });

  // AC: currency.numericCode only accepts exactly 3 digits
  test("numericCode rejects non-digits (pattern [0-9]{3})", async ({ page }) => {
    await ensureCapboSession(page, "/currency");
    await page.getByTestId("currency-create").click({ timeout: 15000 });
    const input = page.getByTestId("currency-numeric-code");
    await fillAngularField(page, input, "AB1");
    await page.keyboard.press('Tab');
    await expect(input.locator('xpath=ancestor::mat-form-field[1]').locator('mat-error').first().or(page.locator('mat-error').first())).toBeVisible({ timeout: 5000 });
    await expect(page.getByTestId("currency-save")).toBeDisabled();
    await page.getByTestId("currency-cancel").click({ timeout: 8000 }).catch(() => {});
  });

  // AC: currency.rounding is limited to a maximum of 1 (clamped or rejected)
  test("roundingIncrement does not accept values above 1", async ({ page }) => {
    await ensureCapboSession(page, "/currency");
    await page.getByTestId("currency-create").click({ timeout: 15000 });
    const input = page.getByTestId("currency-rounding-increment");
    await fillAngularField(page, input, "2");
    await page.keyboard.press('Tab');
    const val = await input.locator('input').first().or(input).inputValue().catch(() => '');
    const clamped = val.replace(',', '.') === "1" || Number(val.replace(',', '.')) <= Number("1");
    const hasError = await input.locator('xpath=ancestor::mat-form-field[1]').locator('mat-error').first().isVisible().catch(() => false);
    expect(clamped || hasError, 'value must clamp to the limit or show a validation error').toBeTruthy();
    await page.getByTestId("currency-cancel").click({ timeout: 8000 }).catch(() => {});
  });

});
